import { useState } from "react";
import type { ChangeEvent, FormEvent, ReactNode } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Link, useLocation, useNavigate, useParams } from "react-router-dom";
import { ArrowLeft, ArrowRight, BookOpen, Check, CheckCircle2, ChevronRight, CircleAlert, CircleHelp, ClipboardCheck, ExternalLink, FileCheck2, FileText, GitBranch, GraduationCap, LayoutDashboard, LogOut, Menu, Pencil, Search, Settings2, ShieldCheck, Sparkles, Target, Upload, UserRound, X, Zap } from "lucide-react";
import { apiGet, apiPatch, apiPost, apiPut } from "@/lib/api";
import type { ActionPlan, AuthResponse, ConflictAnalysis, Dashboard, EligibilityResult, Profile, Readiness, Scholarship, StageResult, StudentDocument, TrackingItem } from "@/lib/types";
import { Brand } from "@/components/Brand";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

const navItems = [
  ["/dashboard", "Dashboard", LayoutDashboard], ["/scholarships", "Scholarships", GraduationCap], ["/compare", "Compare", GitBranch], ["/conflicts", "Conflicts", CircleAlert], ["/documents", "Documents", FileText], ["/readiness", "Readiness", ClipboardCheck], ["/action-plan", "Action plan", Target], ["/tracking", "Tracking", Zap], ["/profile", "Profile", UserRound], ["/settings", "Settings", Settings2],
] as const;

const money = (value: number | null | undefined) => value == null ? "Verify official source" : `₹${(value / 100000).toFixed(1)} lakh`;
const statusCopy: Record<string, string> = { ELIGIBLE: "Eligible", REVIEW: "Review", NOT_ELIGIBLE: "Not eligible" };

export function Workspace({ view, children }: { view: string; children?: ReactNode }) {
  const navigate = useNavigate();
  const location = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const session = useQuery({ queryKey: ["auth-session"], queryFn: () => apiGet<AuthResponse>("/auth/me"), retry: false });
  const displayName = session.data?.profile.full_name ?? "Student";
  const displayInitial = displayName.charAt(0).toUpperCase();
  const profileLabel = session.data?.demo_mode ? "Demo student" : "Student profile";
  const logout = useMutation({ mutationFn: () => apiPost<{ ok: boolean }>("/auth/logout"), onSuccess: () => navigate("/login") });
  return <div className="min-h-svh bg-[#f7f9fb] text-slate-900"><aside className={`fixed inset-y-0 left-0 z-30 flex w-64 flex-col border-r border-slate-200 bg-white px-4 py-5 transition-transform duration-200 md:translate-x-0 ${mobileOpen ? "translate-x-0" : "-translate-x-full"}`}><div className="px-2"><Brand compact /></div><div className="mt-8 flex items-center gap-3 rounded-2xl bg-teal-50 p-3"><div className="flex size-9 items-center justify-center rounded-xl bg-slate-950 text-sm font-extrabold text-teal-200">{displayInitial}</div><div><p data-testid="sidebar-profile-name" className="text-sm font-bold text-slate-900">{displayName}</p><p data-testid="sidebar-profile-label" className="text-[10px] font-semibold uppercase tracking-wider text-teal-700">{profileLabel}</p></div></div><nav className="mt-7 flex-1 space-y-1" aria-label="Workspace navigation">{navItems.map(([path, label, Icon]) => <button key={path} data-testid={`sidebar-${label.toLowerCase().replaceAll(" ", "-")}-link`} onClick={() => { navigate(path); setMobileOpen(false); }} className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-semibold transition-colors ${location.pathname === path || (path === "/conflicts" && location.pathname.startsWith("/conflicts/")) || (path === "/scholarships" && location.pathname.startsWith("/scholarships/")) ? "bg-slate-950 text-white" : "text-slate-600 hover:bg-slate-100 hover:text-slate-950"}`}><Icon className="size-4" />{label}</button>)}</nav><div className="border-t border-slate-200 pt-4"><button data-testid="sidebar-logout-button" onClick={() => logout.mutate()} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm font-semibold text-slate-500 hover:bg-red-50 hover:text-red-700"><LogOut className="size-4" /> Log out</button></div></aside><div className="md:pl-64"><header className="sticky top-0 z-20 border-b border-slate-200/90 bg-white/90 backdrop-blur-xl"><div className="flex h-16 items-center justify-between px-4 sm:px-6 lg:px-8"><div className="flex items-center gap-3"><button data-testid="mobile-navigation-toggle" onClick={() => setMobileOpen(!mobileOpen)} className="rounded-lg p-2 text-slate-600 hover:bg-slate-100 md:hidden"><Menu className="size-5" /></button><div className="md:hidden"><Brand compact /></div><div className="hidden md:block"><p className="font-mono text-[10px] font-bold uppercase tracking-[.2em] text-teal-700">CODEX 2026 · Decision workspace</p><p className="mt-1 text-sm font-bold text-slate-800">{viewLabel(view)}</p></div></div><div className="flex items-center gap-3"><div className="hidden items-center gap-2 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-xs font-semibold text-slate-500 sm:flex"><Search className="size-3.5" /> Search workspace</div><div data-testid="header-profile-avatar" className="flex size-9 items-center justify-center rounded-xl bg-teal-100 text-sm font-extrabold text-teal-800">{displayInitial}</div></div></div><div className="flex gap-2 overflow-x-auto border-t border-slate-100 px-4 py-2 md:hidden">{navItems.slice(0, 6).map(([path, label]) => <button key={path} data-testid={`mobile-${label.toLowerCase().replaceAll(" ", "-")}-link`} onClick={() => navigate(path)} className={`whitespace-nowrap rounded-lg px-3 py-1.5 text-xs font-bold ${location.pathname === path ? "bg-slate-950 text-white" : "bg-slate-100 text-slate-600"}`}>{label}</button>)}</div></header><main className="mx-auto max-w-7xl px-4 py-7 sm:px-6 lg:px-8 lg:py-9">{children}</main></div></div>;
}

function viewLabel(view: string) { return view.split("-").map((part) => part.charAt(0).toUpperCase() + part.slice(1)).join(" "); }
function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="font-mono text-[10px] font-bold uppercase tracking-[.2em] text-teal-700">{eyebrow}</p><h1 data-testid="page-heading" className="mt-2 font-heading text-3xl font-extrabold tracking-tight text-slate-950 sm:text-4xl">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">{description}</p></div>{action}</div>; }
function Metric({ label, value, detail, tone = "slate", testid }: { label: string; value: string | number; detail: string; tone?: "slate" | "teal" | "amber" | "rose"; testid: string }) { const colors = { slate: "bg-white border-slate-200", teal: "bg-teal-50 border-teal-200", amber: "bg-amber-50 border-amber-200", rose: "bg-rose-50 border-rose-200" }; return <div data-testid={testid} className={`rounded-2xl border p-5 ${colors[tone]}`}><p className="text-xs font-bold uppercase tracking-wider text-slate-500">{label}</p><p className="mt-3 font-heading text-3xl font-extrabold text-slate-950">{value}</p><p className="mt-1 text-xs font-semibold text-slate-500">{detail}</p></div>; }
function StatusBadge({ status }: { status: string }) { const styles: Record<string, string> = { ELIGIBLE: "bg-emerald-100 text-emerald-800", REVIEW: "bg-amber-100 text-amber-800", NOT_ELIGIBLE: "bg-rose-100 text-rose-800", Compatible: "bg-emerald-100 text-emerald-800", Conflict: "bg-rose-100 text-rose-800", Review: "bg-amber-100 text-amber-800", "Not Determined": "bg-slate-100 text-slate-700" }; return <span data-testid={`status-badge-${status.toLowerCase().replaceAll(" ", "-")}`} className={`inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wider ${styles[status] ?? "bg-slate-100 text-slate-700"}`}>{status === "ELIGIBLE" || status === "Compatible" ? <Check className="size-3" /> : status === "Conflict" ? <X className="size-3" /> : <CircleAlert className="size-3" />}{statusCopy[status] ?? status}</span>; }
function InfoCard({ children, className = "" }: { children: ReactNode; className?: string }) { return <div className={`rounded-2xl border border-slate-200 bg-white p-5 shadow-sm ${className}`}>{children}</div>; }

export function DashboardPage() {
  const navigate = useNavigate();
  const query = useQuery({ queryKey: ["dashboard"], queryFn: () => apiGet<Dashboard>("/dashboard"), retry: false });
  if (query.isPending) return <Workspace view="dashboard"><Loading /></Workspace>;
  if (query.error || !query.data) return <Workspace view="dashboard"><AuthRequired /></Workspace>;
  const data = query.data;
  const top = data.scholarships.filter((item) => item.overall_status !== "NOT_ELIGIBLE").slice(0, 3);
  return <Workspace view="dashboard"><PageHeading eyebrow="Student command center" title={`Welcome, ${data.profile.full_name}`} description="Your profile, scholarship decisions, and next actions in one place." action={<Button data-testid="dashboard-profile-button" variant="outline" onClick={() => navigate("/profile")}><Pencil /> Edit profile</Button>} /><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><Metric testid="dashboard-potential-matches" label="Potential matches" value={data.matched_count} detail="profile-fit records" tone="teal" /><Metric testid="dashboard-eligible-count" label="Eligible now" value={data.eligible_count} detail="all rules match" /><Metric testid="dashboard-review-count" label="Needs review" value={data.review_count} detail="manual check recommended" tone="amber" /><Metric testid="dashboard-documents-ready" label="Documents ready" value={`${data.documents_ready}/${data.documents_total}`} detail={data.action_count ? "one or more missing" : "checklist complete"} tone={data.action_count ? "rose" : "teal"} /></div><div className="mt-7 grid gap-6 lg:grid-cols-[1.25fr_.75fr]"><InfoCard><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] font-bold uppercase tracking-[.16em] text-teal-700">Scholarships to review</p><h2 className="mt-1 font-heading text-xl font-extrabold text-slate-950">Your strongest matches</h2></div><Button data-testid="dashboard-view-scholarships-button" variant="ghost" onClick={() => navigate("/scholarships")} className="text-teal-700">View all <ArrowRight /></Button></div><div className="mt-5 space-y-3">{top.map((item) => <ScholarshipRow key={item.scholarship.id} item={item} onClick={() => navigate(`/scholarships/${item.scholarship.id}`)} />)}</div></InfoCard><InfoCard><div className="flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-xl bg-amber-100 text-amber-700"><Zap className="size-5" /></div><div><p className="font-mono text-[10px] font-bold uppercase tracking-[.16em] text-amber-700">Your next actions</p><h2 className="mt-1 font-heading text-xl font-extrabold text-slate-950">Keep moving</h2></div></div><div className="mt-5 space-y-4">{data.next_actions.map((action, index) => <button data-testid={`dashboard-next-action-${index + 1}`} key={action} onClick={() => navigate(index === 0 ? "/documents" : index === 1 ? "/compare" : "/readiness")} className="flex w-full items-start gap-3 text-left text-sm font-semibold text-slate-700 hover:text-teal-700"><span className="flex size-6 shrink-0 items-center justify-center rounded-full bg-slate-100 font-mono text-[10px] text-slate-500">{index + 1}</span><span>{action}</span><ChevronRight className="ml-auto mt-0.5 size-4 shrink-0" /></button>)}</div><Button data-testid="dashboard-quick-compatibility-button" onClick={() => navigate("/compare")} className="mt-6 w-full bg-slate-950 text-white hover:bg-teal-700">Check compatibility <GitBranch /></Button></InfoCard></div><div className="mt-6 grid gap-6 lg:grid-cols-3"><InfoCard className="lg:col-span-2"><div className="flex items-center justify-between"><h2 className="font-heading text-lg font-extrabold text-slate-950">Your demo profile</h2><span className="rounded-full bg-teal-50 px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wider text-teal-700">Fictional student</span></div><div className="mt-5 grid gap-4 text-sm sm:grid-cols-4"><ProfileStat label="Course" value={`${data.profile.course} · ${data.profile.branch}`} /><ProfileStat label="Academic" value={`${data.profile.year} · ${data.profile.marks}%`} /><ProfileStat label="State" value={data.profile.state} /><ProfileStat label="Family income" value={money(data.profile.annual_income)} /></div></InfoCard><InfoCard><p className="font-mono text-[10px] font-bold uppercase tracking-[.16em] text-teal-700">Responsible guidance</p><p className="mt-3 text-sm leading-6 text-slate-600">Prototype rules are clearly marked. Always verify the current official rule before applying or accepting.</p><Link data-testid="dashboard-official-sources-link" to="/how-it-works" className="mt-5 inline-flex items-center gap-2 text-sm font-bold text-teal-700">How evidence works <ArrowRight className="size-4" /></Link></InfoCard></div></Workspace>;
}

function ScholarshipRow({ item, onClick }: { item: EligibilityResult; onClick: () => void }) { return <button data-testid={`dashboard-scholarship-${item.scholarship.id}`} onClick={onClick} className="group flex w-full items-center gap-4 rounded-xl border border-slate-200 p-4 text-left transition-all hover:-translate-y-0.5 hover:border-teal-300 hover:shadow-sm"><div className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-slate-950 text-teal-300"><GraduationCap className="size-5" /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-slate-900">{item.scholarship.name}</p><p className="mt-1 truncate text-xs text-slate-500">{item.scholarship.provider}</p></div><StatusBadge status={item.overall_status} /><ChevronRight className="size-4 text-slate-300 transition-transform group-hover:translate-x-1" /></button>; }
function ProfileStat({ label, value }: { label: string; value: string }) { return <div><p className="text-xs font-bold uppercase tracking-wider text-slate-400">{label}</p><p className="mt-1 text-sm font-bold text-slate-800">{value}</p></div>; }

export function ScholarshipsPage() {
  const navigate = useNavigate(); const [search, setSearch] = useState("");
  const query = useQuery({ queryKey: ["scholarships"], queryFn: () => apiGet<EligibilityResult[]>("/scholarships"), retry: false });
  const filtered = query.data?.filter((item) => `${item.scholarship.name} ${item.scholarship.provider}`.toLowerCase().includes(search.toLowerCase())) ?? [];
  return <Workspace view="scholarships"><PageHeading eyebrow="Knowledge base" title="Explore scholarships" description="Search profile-fit records and open the rule behind every eligibility result." action={<Button data-testid="scholarships-compare-button" onClick={() => navigate("/compare")} className="bg-slate-950 text-white hover:bg-teal-700"><GitBranch /> Compare two</Button>} /><div className="mb-6 flex flex-col gap-3 rounded-2xl border border-slate-200 bg-white p-4 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-3 size-4 text-slate-400" /><input data-testid="scholarship-search-input" value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search scholarships or providers" className="h-10 w-full rounded-xl border border-slate-200 bg-slate-50 pl-10 pr-3 text-sm outline-none focus:border-teal-500 focus:bg-white" /></div><div data-testid="scholarships-filter-status" className="flex items-center gap-2 rounded-xl bg-teal-50 px-4 text-xs font-bold text-teal-800"><Sparkles className="size-4" /> {filtered.length} records in your view</div></div>{query.isPending ? <Loading /> : query.error ? <ErrorState message="We could not load the knowledge base." /> : filtered.length === 0 ? <EmptyState /> : <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{filtered.map((item) => <ScholarshipCard key={item.scholarship.id} item={item} onDetails={() => navigate(`/scholarships/${item.scholarship.id}`)} onCompare={() => navigate("/compare")} />)}</div>}</Workspace>;
}

function ScholarshipCard({ item, onDetails, onCompare }: { item: EligibilityResult; onDetails: () => void; onCompare: () => void }) { const { scholarship } = item; return <InfoCard><div className="flex items-start justify-between gap-3"><div className="flex size-10 items-center justify-center rounded-xl bg-teal-50 text-teal-700"><GraduationCap className="size-5" /></div><StatusBadge status={item.overall_status} /></div><h2 data-testid={`scholarship-card-name-${scholarship.id}`} className="mt-5 font-heading text-lg font-extrabold text-slate-950">{scholarship.name}</h2><p className="mt-1 text-xs font-semibold text-slate-500">{scholarship.provider}</p><p className="mt-4 min-h-12 text-sm leading-6 text-slate-600">{scholarship.short_description}</p><div className="mt-5 grid grid-cols-2 gap-3 border-y border-slate-100 py-4 text-xs"><div><p className="font-bold uppercase tracking-wider text-slate-400">Deadline</p><p className="mt-1 font-bold text-slate-800">{scholarship.deadline}</p></div><div><p className="font-bold uppercase tracking-wider text-slate-400">Key rule</p><p className="mt-1 line-clamp-2 font-bold text-slate-800">{scholarship.rule.important_condition}</p></div></div><div className="mt-4 flex items-center justify-between text-xs font-semibold text-slate-500"><span className="flex items-center gap-1.5"><FileCheck2 className="size-4 text-teal-600" /> {item.documents_ready}/{item.documents_total} docs ready</span><span className="text-amber-700">{scholarship.demo_record ? "Demo record" : "Verified"}</span></div><div className="mt-5 flex gap-2"><Button data-testid={`scholarship-view-details-${scholarship.id}`} onClick={onDetails} className="flex-1 bg-slate-950 text-white hover:bg-teal-700">View details</Button><Button data-testid={`scholarship-compare-${scholarship.id}`} variant="outline" onClick={onCompare} size="icon"><GitBranch /></Button></div></InfoCard>; }

export function ScholarshipDetailPage() { const { id = "national-stem" } = useParams(); const navigate = useNavigate(); const query = useQuery({ queryKey: ["scholarship", id], queryFn: () => apiGet<EligibilityResult>(`/scholarships/${id}`), retry: false }); if (query.isPending) return <Workspace view="scholarship-detail"><Loading /></Workspace>; if (query.error || !query.data) return <Workspace view="scholarship-detail"><ErrorState message="This scholarship record is unavailable." /></Workspace>; const item = query.data; const s = item.scholarship; return <Workspace view="scholarship-detail"><button data-testid="scholarship-detail-back-button" onClick={() => navigate(-1)} className="mb-6 flex items-center gap-2 text-sm font-bold text-slate-500 hover:text-teal-700"><ArrowLeft className="size-4" /> Back to scholarships</button><PageHeading eyebrow="Scholarship detail" title={s.name} description={s.short_description} action={<div className="flex flex-wrap gap-2"><Button data-testid="detail-compare-button" variant="outline" onClick={() => navigate("/compare")}><GitBranch /> Compare</Button><a data-testid="detail-official-portal-link" href={s.official_url} target="_blank" rel="noreferrer" className="inline-flex h-8 items-center gap-2 rounded-lg bg-slate-950 px-3 text-sm font-medium text-white hover:bg-teal-700">Official portal <ExternalLink className="size-4" /></a></div>} /><div className="grid gap-6 lg:grid-cols-[1.35fr_.65fr]"><div className="space-y-6"><InfoCard><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider text-slate-400">Why this scholarship matches you</p><h2 className="mt-2 font-heading text-xl font-extrabold text-slate-950">Rule-by-rule explanation</h2></div><StatusBadge status={item.overall_status} /></div><div className="mt-6 space-y-3">{item.conditions.map((condition) => <ConditionRow key={condition.key} condition={condition} />)}</div></InfoCard><InfoCard><div className="flex items-center gap-3"><BookOpen className="size-5 text-teal-700" /><div><h2 className="font-heading text-lg font-extrabold text-slate-950">What to prepare</h2><p className="text-sm text-slate-500">Documents connected to this record</p></div></div><div className="mt-5 grid gap-2 sm:grid-cols-2">{s.required_documents.map((doc) => <div data-testid={`detail-required-document-${doc.toLowerCase().replaceAll(" ", "-")}`} key={doc} className="flex items-center gap-2 rounded-xl bg-slate-50 px-3 py-3 text-sm font-semibold text-slate-700"><FileCheck2 className="size-4 text-teal-600" /> {doc}</div>)}</div></InfoCard></div><div className="space-y-6"><InfoCard className="bg-slate-950 text-white"><p className="font-mono text-[10px] uppercase tracking-[.16em] text-teal-300">Decision snapshot</p><p className="mt-3 text-3xl font-extrabold">{item.documents_ready}/{item.documents_total}</p><p className="mt-1 text-sm text-slate-300">documents ready</p><div className="mt-6 h-2 rounded-full bg-white/10"><div className="h-2 rounded-full bg-teal-400" style={{ width: `${(item.documents_ready / item.documents_total) * 100}%` }} /></div><p className="mt-4 text-sm leading-6 text-slate-300">{item.next_action}. The authority remains responsible for final verification.</p><Button data-testid="detail-documents-button" onClick={() => navigate("/documents")} className="mt-5 w-full bg-teal-500 font-bold text-slate-950 hover:bg-teal-300">Open document centre <ArrowRight /></Button></InfoCard><InfoCard><p className="font-mono text-[10px] uppercase tracking-[.16em] text-amber-700">Evidence status</p><h3 className="mt-2 font-heading text-lg font-extrabold text-slate-950">{s.evidence.verification_status}</h3><p className="mt-2 text-sm leading-6 text-slate-600">{s.evidence.source_name}</p><div className="mt-4 rounded-xl bg-amber-50 p-4 text-sm leading-6 text-amber-900"><p className="font-bold">Rule summary</p><p className="mt-1">{s.evidence.rule_text}</p>{s.evidence.clause && <p className="mt-2 font-mono text-xs">{s.evidence.clause} · Checked {s.evidence.date_checked}</p>}</div></InfoCard></div></div></Workspace>; }

function ConditionRow({ condition }: { condition: EligibilityResult["conditions"][number] }) { const good = condition.status === "MATCH"; const review = condition.status === "REVIEW" || condition.status === "NOT_AVAILABLE"; return <div data-testid={`eligibility-condition-${condition.key}`} className={`rounded-xl border p-4 ${good ? "border-emerald-200 bg-emerald-50/60" : review ? "border-amber-200 bg-amber-50/60" : "border-rose-200 bg-rose-50/60"}`}><div className="flex items-start gap-3"><div className={`mt-0.5 flex size-6 shrink-0 items-center justify-center rounded-full ${good ? "bg-emerald-200 text-emerald-800" : review ? "bg-amber-200 text-amber-800" : "bg-rose-200 text-rose-800"}`}>{good ? <Check className="size-3.5" /> : review ? <CircleAlert className="size-3.5" /> : <X className="size-3.5" />}</div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-sm font-extrabold text-slate-900">{condition.label}</p><span className="text-[10px] font-extrabold uppercase tracking-wider text-slate-500">{condition.status === "MATCH" ? "Match" : condition.status === "FAIL" ? "Not eligible" : "Review"}</span></div><div className="mt-2 grid gap-2 text-xs sm:grid-cols-2"><p><span className="font-bold text-slate-500">Your value:</span> {condition.student_value}</p><p><span className="font-bold text-slate-500">Required:</span> {condition.required}</p></div><p className="mt-2 text-xs leading-5 text-slate-600">{condition.explanation}</p></div></div></div>; }

export function DocumentsPage() { const queryClient = useQueryClient(); const query = useQuery({ queryKey: ["documents"], queryFn: () => apiGet<StudentDocument[]>("/documents"), retry: false }); const update = useMutation({ mutationFn: ({ id, available }: { id: string; available: boolean }) => apiPatch<StudentDocument>(`/documents/${id}`, { available }), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ["documents"] }); queryClient.invalidateQueries({ queryKey: ["dashboard"] }); toast.success("Document readiness updated"); } }); const docs = query.data ?? []; return <Workspace view="documents"><PageHeading eyebrow="Document centre" title="Prepare with confidence" description="Track the evidence that supports your scholarship conditions. Uploading is represented by a local readiness toggle for this demo." action={<div className="rounded-xl bg-teal-50 px-4 py-3 text-xs font-bold text-teal-800">{docs.filter((doc) => doc.available).length}/{docs.length} available</div>} />{query.isPending ? <Loading /> : query.error ? <ErrorState message="Unable to load your document centre." /> : <div className="grid gap-6 lg:grid-cols-[1.2fr_.8fr]"><InfoCard><div className="flex items-center justify-between"><div><h2 className="font-heading text-xl font-extrabold text-slate-950">Your documents</h2><p className="mt-1 text-sm text-slate-500">Available · Missing · Manual review</p></div><Button data-testid="documents-readiness-button" variant="outline" onClick={() => window.scrollTo({ top: document.body.scrollHeight, behavior: "smooth" })}><ClipboardCheck /> Readiness</Button></div><div className="mt-5 space-y-3">{docs.map((doc) => <DocumentRow key={doc.id} doc={doc} onToggle={() => update.mutate({ id: doc.id, available: !doc.available })} busy={update.isPending} />)}</div></InfoCard><div className="space-y-6"><InfoCard className="bg-teal-50"><div className="flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-xl bg-teal-700 text-white"><Upload className="size-5" /></div><div><h2 className="font-heading text-lg font-extrabold text-slate-950">Add a document</h2><p className="text-sm text-slate-600">Demo-ready local status</p></div></div><p className="mt-5 text-sm leading-6 text-slate-700">Use “Mark available” to demonstrate the readiness workflow. No document leaves this demo environment.</p><Button data-testid="documents-upload-demo-button" onClick={() => { const missing = docs.find((doc) => !doc.available); if (missing) update.mutate({ id: missing.id, available: true }); }} className="mt-5 w-full bg-slate-950 text-white hover:bg-teal-700"><Upload /> Mark next missing available</Button></InfoCard><InfoCard><p className="font-mono text-[10px] font-bold uppercase tracking-[.16em] text-amber-700">Application readiness note</p><p className="mt-3 text-sm leading-6 text-slate-600">You may meet the eligibility conditions, but a missing domicile certificate can still block a complete application.</p></InfoCard></div></div>}</Workspace>; }
function DocumentRow({ doc, onToggle, busy }: { doc: StudentDocument; onToggle: () => void; busy: boolean }) { return <div data-testid={`document-row-${doc.id}`} className="flex flex-col gap-3 rounded-xl border border-slate-200 p-4 sm:flex-row sm:items-center"><div className={`flex size-9 shrink-0 items-center justify-center rounded-xl ${doc.available ? "bg-emerald-100 text-emerald-700" : "bg-rose-100 text-rose-700"}`}>{doc.available ? <Check className="size-4" /> : <CircleAlert className="size-4" />}</div><div className="min-w-0 flex-1"><p className="text-sm font-extrabold text-slate-900">{doc.name}</p><p className="mt-1 text-xs text-slate-500">{doc.available ? doc.extracted_value ?? "Available for review" : "Not uploaded yet"}</p></div><div className="flex items-center gap-2"><span className={`text-[10px] font-extrabold uppercase tracking-wider ${doc.available ? "text-emerald-700" : "text-rose-700"}`}>{doc.available ? doc.extraction_status : "Missing"}</span><Button data-testid={`document-toggle-${doc.id}`} disabled={busy} variant="outline" size="sm" onClick={onToggle}>{doc.available ? "Mark missing" : "Mark available"}</Button></div></div>; }

export function ComparePage() { const navigate = useNavigate(); const [ids, setIds] = useState(["national-stem", "maharashtra-support"]); const query = useQuery({ queryKey: ["scholarships"], queryFn: () => apiGet<EligibilityResult[]>("/scholarships"), retry: false }); const items = query.data ?? []; const pick = (index: number) => (event: ChangeEvent<HTMLSelectElement>) => setIds(index === 0 ? [event.target.value, ids[1]] : [ids[0], event.target.value]); const first = items.find((item) => item.scholarship.id === ids[0]); const second = items.find((item) => item.scholarship.id === ids[1]); return <Workspace view="compare"><PageHeading eyebrow="Decision support" title="Compare scholarships" description="See where two individually eligible opportunities differ before checking how they interact." action={<Button data-testid="compare-check-compatibility-button" onClick={() => navigate(`/conflicts/${ids[0]}-${ids[1]}`)} disabled={!first || !second || ids[0] === ids[1]} className="bg-slate-950 text-white hover:bg-teal-700"><GitBranch /> Check compatibility</Button>} />{query.isPending ? <Loading /> : <><div className="grid gap-4 md:grid-cols-2"><ComparePicker label="Scholarship A" value={ids[0]} onChange={pick(0)} items={items} testid="compare-scholarship-a-select" /><ComparePicker label="Scholarship B" value={ids[1]} onChange={pick(1)} items={items} testid="compare-scholarship-b-select" /></div>{first && second ? <InfoCard className="mt-6 overflow-hidden p-0"><div className="grid grid-cols-[1.15fr_1fr_1fr] border-b border-slate-200 bg-slate-50 text-xs font-bold uppercase tracking-wider text-slate-500"><div className="p-4">Decision lens</div><div className="border-l border-slate-200 p-4 text-slate-900">{first.scholarship.name}</div><div className="border-l border-slate-200 p-4 text-slate-900">{second.scholarship.name}</div></div>{[["Eligibility", statusCopy[first.overall_status], statusCopy[second.overall_status]], ["Academic", `≥ ${first.scholarship.rule.minimum_marks}%`, `≥ ${second.scholarship.rule.minimum_marks}%`], ["Income limit", money(first.scholarship.rule.income_limit), money(second.scholarship.rule.income_limit)], ["State", first.scholarship.rule.state ?? "Open to eligible states", second.scholarship.rule.state ?? "Open to eligible states"], ["Documents", `${first.scholarship.required_documents.length} required`, `${second.scholarship.required_documents.length} required`], ["Deadline", first.scholarship.deadline, second.scholarship.deadline]].map(([label, a, b]) => <div data-testid={`compare-row-${(label as string).toLowerCase().replaceAll(" ", "-")}`} key={label as string} className="grid grid-cols-[1.15fr_1fr_1fr] border-b border-slate-100 text-sm last:border-0"><div className="p-4 font-bold text-slate-500">{label as string}</div><div className="border-l border-slate-100 p-4 font-semibold text-slate-800">{a as string}</div><div className="border-l border-slate-100 p-4 font-semibold text-slate-800">{b as string}</div></div>)}</InfoCard> : <EmptyState />}</>}</Workspace>; }
function ComparePicker({ label, value, onChange, items, testid }: { label: string; value: string; onChange: (event: ChangeEvent<HTMLSelectElement>) => void; items: EligibilityResult[]; testid: string }) { return <label className="rounded-2xl border border-slate-200 bg-white p-5 text-sm font-bold text-slate-700">{label}<select data-testid={testid} value={value} onChange={onChange} className="mt-3 h-11 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm font-semibold outline-none focus:border-teal-500">{items.map((item) => <option key={item.scholarship.id} value={item.scholarship.id}>{item.scholarship.name}</option>)}</select></label>; }

export function ConflictPage() { const { id } = useParams(); const navigate = useNavigate(); const ids = (id ?? "national-stem-maharashtra-support").split("-"); const pair = ids.length > 2 ? [ids.slice(0, -2).join("-"), ids.slice(-2).join("-")] : ["national-stem", "maharashtra-support"]; const query = useQuery({ queryKey: ["conflict", pair.join("-")], queryFn: () => apiPost<ConflictAnalysis>("/conflicts/analyze", { scholarship_ids: pair }), retry: false }); const [active, setActive] = useState<StageResult | null>(null); if (query.isPending) return <Workspace view="conflicts"><Loading /></Workspace>; if (query.error || !query.data) return <Workspace view="conflicts"><ErrorState message="Compatibility could not be determined from available evidence." /></Workspace>; const data = query.data; const activeStage = active ?? data.stages.find((stage) => stage.status === "Conflict") ?? data.stages[0]; return <Workspace view="conflicts"><PageHeading eyebrow="Core innovation" title="Scholarship compatibility" description="See how selected scholarships may interact across their lifecycle." action={<Button data-testid="conflict-back-compare-button" variant="outline" onClick={() => navigate("/compare")}><ArrowLeft /> Change pair</Button>} /><div className="grid gap-6 xl:grid-cols-[1.15fr_.85fr]"><InfoCard className="overflow-hidden bg-slate-950 text-white"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] text-teal-300">Stage-aware conflict graph</p><h2 className="mt-2 font-heading text-2xl font-extrabold">{data.scholarship_a.name} <span className="text-teal-300">↔</span> {data.scholarship_b.name}</h2></div><StatusBadge status={data.overall_status} /></div><div data-testid="conflict-graph" className="relative mt-8 min-h-[300px] overflow-hidden rounded-2xl border border-white/10 bg-[#111c32]"><svg className="absolute inset-0 h-full w-full" aria-hidden="true"><line x1="50%" y1="50%" x2="23%" y2="27%" stroke="#2dd4bf" strokeDasharray="6 6" strokeWidth="2" /><line x1="50%" y1="50%" x2="77%" y2="27%" stroke="#f59e0b" strokeDasharray="6 6" strokeWidth="2" /><line x1="28%" y1="27%" x2="72%" y2="27%" stroke="#fb7185" strokeWidth="3" /></svg><button data-testid="conflict-scholarship-a-node" onClick={() => navigate(`/scholarships/${data.scholarship_a.id}`)} className="absolute left-[5%] top-[13%] w-[36%] rounded-xl border-2 border-teal-400 bg-slate-900 p-3 text-left shadow-lg transition-transform hover:scale-[1.03]"><p className="text-[9px] font-bold uppercase tracking-wider text-teal-300">Scholarship A</p><p className="mt-2 line-clamp-2 text-sm font-extrabold text-white">{data.scholarship_a.name}</p></button><button data-testid="conflict-scholarship-b-node" onClick={() => navigate(`/scholarships/${data.scholarship_b.id}`)} className="absolute right-[5%] top-[13%] w-[36%] rounded-xl border-2 border-teal-400 bg-slate-900 p-3 text-left shadow-lg transition-transform hover:scale-[1.03]"><p className="text-[9px] font-bold uppercase tracking-wider text-teal-300">Scholarship B</p><p className="mt-2 line-clamp-2 text-sm font-extrabold text-white">{data.scholarship_b.name}</p></button><button data-testid="conflict-student-node" className="absolute left-1/2 top-1/2 flex size-24 -translate-x-1/2 -translate-y-1/2 flex-col items-center justify-center rounded-full border-4 border-teal-400 bg-teal-950 text-center shadow-xl shadow-teal-500/20"><UserRound className="size-6 text-teal-300" /><span className="mt-1 text-xs font-extrabold text-white">STUDENT</span><span className="text-[9px] text-teal-200">{data.student_name}</span></button><button data-testid="conflict-relationship-edge" onClick={() => setActive(data.stages.find((stage) => stage.status === "Conflict") ?? data.stages[0])} className="absolute left-1/2 top-[24%] -translate-x-1/2 rounded-full border border-rose-300/50 bg-rose-500/20 px-3 py-1 text-[10px] font-extrabold uppercase tracking-wider text-rose-200 transition-colors hover:bg-rose-500/40">Why?</button></div><p className="mt-4 text-xs leading-5 text-slate-400">Click a scholarship node to inspect its rules, or click the relationship to see the evidence behind the warning.</p></InfoCard><InfoCard><div className="flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-xl bg-teal-50 text-teal-700"><GitBranch className="size-5" /></div><div><p className="font-mono text-[10px] font-bold uppercase tracking-[.16em] text-teal-700">Lifecycle timeline</p><h2 className="mt-1 font-heading text-xl font-extrabold text-slate-950">Where the relationship changes</h2></div></div><div className="mt-6 space-y-2">{data.stages.map((stage, index) => <button data-testid={`conflict-stage-${stage.id}`} key={stage.id} onClick={() => setActive(stage)} className={`flex w-full items-center gap-3 rounded-xl border p-3 text-left transition-colors ${activeStage.id === stage.id ? "border-teal-400 bg-teal-50" : "border-slate-200 hover:border-teal-200"}`}><span className="flex size-7 shrink-0 items-center justify-center rounded-full bg-slate-100 font-mono text-[10px] font-bold text-slate-500">0{index + 1}</span><span className="min-w-0 flex-1"><span className="block text-sm font-extrabold text-slate-900">{stage.label}</span><span className="mt-0.5 block truncate text-xs text-slate-500">{stage.summary}</span></span><StatusBadge status={stage.status} /></button>)}</div><div data-testid="conflict-recommendation" className="mt-5 rounded-xl bg-amber-50 p-4 text-sm leading-6 text-amber-900"><p className="font-bold">What this means</p><p className="mt-1">{data.recommendation}</p></div></InfoCard></div><div className="mt-6 grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><InfoCard><div className="flex items-center justify-between gap-3"><div><p className="font-mono text-[10px] font-bold uppercase tracking-[.16em] text-teal-700">Selected stage</p><h2 className="mt-1 font-heading text-xl font-extrabold text-slate-950">{activeStage.label}</h2></div><StatusBadge status={activeStage.status} /></div><p data-testid="conflict-stage-why" className="mt-5 text-sm leading-7 text-slate-700">{activeStage.why}</p><Button data-testid="conflict-why-button" onClick={() => setActive(activeStage)} className="mt-5 bg-slate-950 text-white hover:bg-teal-700"><CircleHelp /> Why this result?</Button></InfoCard><EvidencePanel stage={activeStage} /></div><p className="mt-6 text-xs leading-5 text-slate-500">{data.disclaimer}</p></Workspace>; }

function EvidencePanel({ stage }: { stage: StageResult }) { const evidence = stage.evidence; return <InfoCard className="border-teal-200 bg-teal-50/50"><div className="flex items-center gap-3"><ShieldCheck className="size-5 text-teal-700" /><div><p className="font-mono text-[10px] font-bold uppercase tracking-[.16em] text-teal-700">Evidence-locked explanation</p><h2 className="mt-1 font-heading text-xl font-extrabold text-slate-950">Official evidence</h2></div></div>{evidence ? <div data-testid="evidence-explanation-panel" className="mt-5 space-y-4"><div><p className="text-xs font-bold uppercase tracking-wider text-slate-500">Source</p><p className="mt-1 text-sm font-bold text-slate-900">{evidence.source_name}</p></div><div className="rounded-xl border border-teal-200 bg-white p-4"><p className="text-xs font-bold uppercase tracking-wider text-slate-500">Rule</p><p className="mt-2 text-sm leading-6 text-slate-700">{evidence.rule_text}</p>{evidence.clause && <p data-testid="evidence-clause" className="mt-3 font-mono text-xs font-bold text-teal-800">{evidence.clause}</p>}</div><div className="flex flex-wrap items-center justify-between gap-3 text-xs"><span className="font-bold text-slate-500">Date checked: <span className="text-slate-800">{evidence.date_checked}</span></span><span className="rounded-full bg-amber-100 px-2.5 py-1 font-extrabold uppercase tracking-wider text-amber-800">{evidence.verification_status}</span></div><a data-testid="evidence-official-rule-link" href={evidence.source_url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 text-sm font-extrabold text-teal-800 hover:underline">View official rule <ExternalLink className="size-4" /></a></div> : <p data-testid="evidence-unavailable-message" className="mt-5 rounded-xl bg-white p-4 text-sm leading-6 text-slate-600">Evidence unavailable — manual verification required. No definite restriction is being claimed.</p>}</InfoCard>; }

export function ReadinessPage() { const query = useQuery({ queryKey: ["readiness"], queryFn: () => apiGet<Readiness>("/readiness"), retry: false }); if (query.isPending) return <Workspace view="readiness"><Loading /></Workspace>; if (query.error || !query.data) return <Workspace view="readiness"><ErrorState message="Readiness is unavailable right now." /></Workspace>; const d = query.data; const checks = [["Eligibility checked", d.eligibility_checked, "Rules have been evaluated against your profile."], ["Documents", d.documents_ready === d.documents_total, `${d.documents_ready} of ${d.documents_total} documents available.`], ["Compatibility reviewed", d.compatibility_reviewed, "Compare selected awards before accepting both."], ["Official evidence", d.official_evidence_available, "Evidence is available for the demo relationship."]]; return <Workspace view="readiness"><PageHeading eyebrow="Ready when you are" title="Application readiness" description="A final decision-support checklist before you move to an official portal." /><div className="grid gap-6 lg:grid-cols-[.85fr_1.15fr]"><InfoCard className="bg-slate-950 text-white"><p className="font-mono text-[10px] uppercase tracking-[.16em] text-teal-300">Overall status</p><div className="mt-5 flex items-end justify-between"><div><h2 data-testid="readiness-overall-status" className="font-heading text-3xl font-extrabold">{d.overall_status}</h2><p className="mt-2 max-w-xs text-sm leading-6 text-slate-300">{d.message}</p></div><div className="font-mono text-4xl font-bold text-teal-300">{Math.round((d.documents_ready / d.documents_total) * 100)}%</div></div><div className="mt-8 h-3 rounded-full bg-white/10"><div className="h-3 rounded-full bg-teal-400" style={{ width: `${(d.documents_ready / d.documents_total) * 100}%` }} /></div><Link data-testid="readiness-action-plan-link" to="/action-plan" className="mt-7 inline-flex items-center gap-2 text-sm font-extrabold text-teal-300">Open next action plan <ArrowRight className="size-4" /></Link></InfoCard><InfoCard><h2 className="font-heading text-xl font-extrabold text-slate-950">Decision checklist</h2><div className="mt-5 space-y-3">{checks.map(([label, done, detail], index) => <div data-testid={`readiness-check-${index + 1}`} key={label as string} className="flex gap-3 rounded-xl border border-slate-200 p-4"><div className={`flex size-8 shrink-0 items-center justify-center rounded-full ${done ? "bg-emerald-100 text-emerald-700" : "bg-amber-100 text-amber-700"}`}>{done ? <Check className="size-4" /> : <CircleAlert className="size-4" />}</div><div><p className="text-sm font-extrabold text-slate-900">{label as string}</p><p className="mt-1 text-xs leading-5 text-slate-500">{detail as string}</p></div></div>)}</div></InfoCard></div></Workspace>; }

export function ActionPlanPage() { const query = useQuery({ queryKey: ["action-plan"], queryFn: () => apiGet<ActionPlan>("/action-plan"), retry: false }); return <Workspace view="action-plan"><PageHeading eyebrow="Your next move" title="Next action plan" description="A short, practical sequence for moving from understanding to official application." />{query.isPending ? <Loading /> : query.error || !query.data ? <ErrorState message="Could not load your action plan." /> : <div className="max-w-3xl space-y-4">{query.data.actions.map((action, index) => <InfoCard key={action.id} className="flex gap-4"><div className={`flex size-10 shrink-0 items-center justify-center rounded-xl ${action.done ? "bg-emerald-100 text-emerald-700" : "bg-teal-50 text-teal-700"}`}>{action.done ? <Check className="size-5" /> : <span className="font-mono font-bold">0{index + 1}</span>}</div><div className="flex-1"><div className="flex flex-wrap items-center gap-3"><h2 data-testid={`action-plan-title-${action.id}`} className="font-heading text-lg font-extrabold text-slate-950">{action.title}</h2><span className="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-extrabold uppercase tracking-wider text-slate-600">{action.priority}</span></div><p className="mt-2 text-sm leading-6 text-slate-600">{action.description}</p></div><ChevronRight className="mt-2 size-5 text-slate-300" /></InfoCard>)}<InfoCard className="mt-7 border-amber-200 bg-amber-50"><p className="flex items-center gap-2 text-sm font-extrabold text-amber-900"><ShieldCheck className="size-4" /> Before you apply</p><p className="mt-2 text-sm leading-6 text-amber-900/80">Open the official portal from the scholarship detail page and verify the current rule. Vidyadwar does not replace the official application system.</p></InfoCard></div>}</Workspace>; }

export function TrackingPage() { const queryClient = useQueryClient(); const query = useQuery({ queryKey: ["tracking"], queryFn: () => apiGet<TrackingItem[]>("/tracking"), retry: false }); const update = useMutation({ mutationFn: ({ id, stage }: { id: string; stage: string }) => apiPatch<TrackingItem>(`/tracking/${id}`, { stage }), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ["tracking"] }); toast.success("Personal tracking updated"); } }); return <Workspace view="tracking"><PageHeading eyebrow="Personal workspace" title="Application tracking" description="Track your preparation stages for your own reference. This is not official application status." />{query.isPending ? <Loading /> : query.error || !query.data ? <ErrorState message="Tracking is unavailable right now." /> : <div className="grid gap-5 md:grid-cols-2">{query.data.slice(0, 4).map((item) => <InfoCard key={item.scholarship_id}><div className="flex items-start justify-between gap-3"><div><p className="font-heading text-lg font-extrabold text-slate-950">{item.scholarship_name}</p><p className="mt-1 text-xs text-slate-500">Personal tracking only</p></div><span className="rounded-full bg-teal-50 px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wider text-teal-700">{item.stage}</span></div><div className="mt-6 flex items-center gap-1">{["Discovered", "Eligibility Checked", "Documents", "Compatibility Reviewed", "Applied"].map((stage, index) => <div key={stage} className={`h-2 flex-1 rounded-full ${index <= ["Discovered", "Eligibility Checked", "Documents", "Compatibility Reviewed", "Applied"].indexOf(item.stage) ? "bg-teal-500" : "bg-slate-100"}`} />)}</div><label className="mt-5 block text-xs font-bold uppercase tracking-wider text-slate-500">Update stage<select data-testid={`tracking-select-${item.scholarship_id}`} value={item.stage} onChange={(event) => update.mutate({ id: item.scholarship_id, stage: event.target.value })} className="mt-2 h-10 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm font-semibold normal-case tracking-normal text-slate-800"><option>Discovered</option><option>Eligibility Checked</option><option>Documents</option><option>Compatibility Reviewed</option><option>Applied</option></select></label></InfoCard>)}</div>}</Workspace>; }

export function ProfilePage() { const queryClient = useQueryClient(); const query = useQuery({ queryKey: ["profile"], queryFn: () => apiGet<Profile>("/profile"), retry: false }); const [form, setForm] = useState<Profile | null>(null); const save = useMutation({ mutationFn: (payload: Profile) => apiPut<Profile>("/profile", payload), onSuccess: (data) => { setForm(data); queryClient.invalidateQueries({ queryKey: ["profile"] }); queryClient.invalidateQueries({ queryKey: ["dashboard"] }); toast.success("Profile saved"); } }); if (query.isPending) return <Workspace view="profile"><Loading /></Workspace>; if (query.error || !query.data) return <Workspace view="profile"><AuthRequired /></Workspace>; const current = form ?? query.data; const update = (key: keyof Profile, value: string | number | boolean) => setForm({ ...current, [key]: value }); const submit = (event: FormEvent) => { event.preventDefault(); if (form) save.mutate(form); else toast.success("Your demo profile is already saved"); }; return <Workspace view="profile"><PageHeading eyebrow="Student profile" title="Your profile powers the matching" description="Keep only the information needed to explain scholarship conditions clearly." action={<span className="rounded-full bg-teal-50 px-3 py-2 text-xs font-extrabold uppercase tracking-wider text-teal-800">Fictional demo student</span>} /><form onSubmit={submit} className="grid gap-6 lg:grid-cols-[1.15fr_.85fr]"><InfoCard><FormSection title="Academic information" icon={<GraduationCap className="size-5" />}><div className="grid gap-4 sm:grid-cols-2"><TextField label="Full name" value={current.full_name} onChange={(value) => update("full_name", value)} testid="profile-full-name-input" /><TextField label="Course" value={current.course} onChange={(value) => update("course", value)} testid="profile-course-input" /><TextField label="Branch" value={current.branch} onChange={(value) => update("branch", value)} testid="profile-branch-input" /><TextField label="Current year" value={current.year} onChange={(value) => update("year", value)} testid="profile-year-input" /><TextField label="Marks / percentage" value={String(current.marks)} type="number" onChange={(value) => update("marks", Number(value))} testid="profile-marks-input" /></div></FormSection><FormSection title="Personal and scheme information" icon={<UserRound className="size-5" />}><div className="grid gap-4 sm:grid-cols-2"><TextField label="State / domicile" value={current.state} onChange={(value) => update("state", value)} testid="profile-state-input" /><TextField label="Category" value={current.category} onChange={(value) => update("category", value)} testid="profile-category-input" /><TextField label="Gender" value={current.gender} onChange={(value) => update("gender", value)} testid="profile-gender-input" /><TextField label="Disability status" value={current.disability_status} onChange={(value) => update("disability_status", value)} testid="profile-disability-input" /></div></FormSection><FormSection title="Financial context" icon={<ShieldCheck className="size-5" />}><div className="grid gap-4 sm:grid-cols-2"><TextField label="Annual family income" value={String(current.annual_income)} type="number" onChange={(value) => update("annual_income", Number(value))} testid="profile-income-input" /><ToggleField label="Income certificate available" value={current.income_certificate} onChange={(value) => update("income_certificate", value)} testid="profile-income-certificate-toggle" /><ToggleField label="Receiving scholarship" value={current.receiving_scholarship} onChange={(value) => update("receiving_scholarship", value)} testid="profile-scholarship-toggle" /><ToggleField label="Receiving stipend" value={current.receiving_stipend} onChange={(value) => update("receiving_stipend", value)} testid="profile-stipend-toggle" /></div></FormSection><Button data-testid="profile-save-button" disabled={save.isPending} className="h-11 bg-slate-950 text-white hover:bg-teal-700">{save.isPending ? "Saving…" : "Save profile"} <Check /></Button></InfoCard><InfoCard className="h-fit bg-slate-950 text-white"><p className="font-mono text-[10px] uppercase tracking-[.16em] text-teal-300">Why we ask</p><h2 className="mt-3 font-heading text-2xl font-extrabold">A smaller profile, a clearer answer.</h2><p className="mt-4 text-sm leading-6 text-slate-300">These fields map directly to seeded eligibility conditions. No black-box “AI says eligible” labels.</p><div className="mt-8 space-y-4">{["Course and marks map to academic rules", "Income and state reveal key conditions", "Benefits inform the conflict conversation"].map((text) => <div key={text} className="flex items-start gap-3 text-sm font-semibold text-slate-200"><Check className="mt-0.5 size-4 shrink-0 text-teal-300" />{text}</div>)}</div></InfoCard></form></Workspace>; }
function FormSection({ title, icon, children }: { title: string; icon: ReactNode; children: ReactNode }) { return <section className="mb-8 border-b border-slate-100 pb-8 last:mb-0 last:border-0 last:pb-0"><div className="mb-5 flex items-center gap-3"><div className="flex size-9 items-center justify-center rounded-xl bg-teal-50 text-teal-700">{icon}</div><h2 className="font-heading text-lg font-extrabold text-slate-950">{title}</h2></div>{children}</section>; }
function TextField({ label, value, onChange, testid, type = "text" }: { label: string; value: string; onChange: (value: string) => void; testid: string; type?: string }) { return <label className="block text-sm font-semibold text-slate-700">{label}<input data-testid={testid} type={type} value={value} onChange={(event) => onChange(event.target.value)} className="mt-2 h-10 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm outline-none focus:border-teal-500 focus:bg-white" /></label>; }
function ToggleField({ label, value, onChange, testid }: { label: string; value: boolean; onChange: (value: boolean) => void; testid: string }) { return <label className="flex items-center gap-3 rounded-xl border border-slate-200 p-3 text-sm font-semibold text-slate-700"><input data-testid={testid} type="checkbox" checked={value} onChange={(event) => onChange(event.target.checked)} className="size-4 accent-teal-700" />{label}</label>; }

export function SettingsPage() { const navigate = useNavigate(); return <Workspace view="settings"><PageHeading eyebrow="Workspace settings" title="Settings" description="Control the local demo workspace and understand what your data powers." /><div className="max-w-2xl space-y-5"><InfoCard><div className="flex items-start gap-4"><div className="flex size-10 items-center justify-center rounded-xl bg-teal-50 text-teal-700"><ShieldCheck className="size-5" /></div><div><h2 className="font-heading text-lg font-extrabold text-slate-950">Local demo session</h2><p className="mt-2 text-sm leading-6 text-slate-600">This MVP uses a local session cookie and a fictional Aarav record. No external API credentials are required for the core journey.</p></div></div></InfoCard><InfoCard><h2 className="font-heading text-lg font-extrabold text-slate-950">Responsible product positioning</h2><p className="mt-3 text-sm leading-6 text-slate-600">Vidyadwar is a decision-support system. Official scholarship rules remain the final authority. Always verify important conditions on the official source.</p><Button data-testid="settings-profile-button" onClick={() => navigate("/profile")} variant="outline" className="mt-5">Review profile <ArrowRight /></Button></InfoCard></div></Workspace>; }

export function PublicInfoPage({ kind }: { kind: "how-it-works" | "privacy" | "terms" }) { const content = kind === "how-it-works" ? { eyebrow: "The Vidyadwar method", title: "From a scholarship list to a confident next step.", intro: "Vidyadwar turns complex scholarship information into a transparent, student-friendly decision workflow.", blocks: ["Create profile", "Discover scholarships", "Understand eligibility", "Check documents", "Compare two records", "Check stage-aware conflicts", "Verify official evidence", "Review readiness", "Proceed to the official portal"] } : kind === "privacy" ? { eyebrow: "Privacy", title: "Your information supports your workflow.", intro: "The demo uses profile and document-status information to calculate scholarship guidance. Keep production deployments subject to your own privacy review.", blocks: ["Profile information is used to evaluate structured prototype conditions.", "Document statuses are used to show readiness and missing actions.", "This MVP does not need external AI credentials or send student data to an AI provider."] } : { eyebrow: "Terms", title: "Use guidance as a starting point.", intro: "Scholarship information can change. Review the official source before making an application or accepting an award.", blocks: ["Vidyadwar does not guarantee eligibility, selection, approval, payment, or disbursement.", "Prototype / Demo Rule records are not official scholarship rules.", "The official scholarship authority remains responsible for the final decision."] }; return <div className="min-h-svh bg-[#fafafc] text-slate-900"><header className="border-b border-slate-200 bg-white"><div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-4 lg:px-8"><Brand /><Link data-testid={`${kind}-back-home-link`} to="/" className="flex items-center gap-2 text-sm font-bold text-slate-600 hover:text-teal-700"><ArrowLeft className="size-4" /> Back home</Link></div></header><main className="mx-auto max-w-4xl px-5 py-16 lg:px-8 lg:py-24"><p className="font-mono text-xs font-bold uppercase tracking-[.2em] text-teal-700">{content.eyebrow}</p><h1 data-testid={`${kind}-heading`} className="mt-4 font-heading text-4xl font-extrabold tracking-tight text-slate-950 sm:text-5xl">{content.title}</h1><p className="mt-5 max-w-2xl text-lg leading-8 text-slate-600">{content.intro}</p><div className="mt-12 space-y-3">{content.blocks.map((block, index) => <div data-testid={`${kind}-block-${index + 1}`} key={block} className="flex gap-4 rounded-2xl border border-slate-200 bg-white p-5"><span className="font-mono text-sm font-bold text-teal-700">0{index + 1}</span><p className="text-sm leading-6 text-slate-700">{kind === "how-it-works" ? <><span className="font-extrabold text-slate-950">{block}</span> — {index === 0 ? "Start with only the fields needed for scholarship rules." : index === 5 ? "See whether a relationship appears at application, acceptance, or receiving." : index === 6 ? "Open the stored source, rule, clause, and checked date." : "Move one transparent step at a time."}</> : block}</p></div>)}</div><div className="mt-10 rounded-2xl border border-amber-200 bg-amber-50 p-5 text-sm leading-6 text-amber-900"><span className="font-bold">Important:</span> Vidyadwar provides decision-support information. Final eligibility, approval, verification and disbursement are determined by the respective official scholarship authority.</div></main></div>; }

function Loading() { return <div data-testid="loading-state" className="rounded-2xl border border-slate-200 bg-white p-10 text-center"><div className="mx-auto size-8 animate-spin rounded-full border-4 border-slate-200 border-t-teal-600" /><p className="mt-4 text-sm font-semibold text-slate-500">Loading your decision workspace…</p></div>; }
function EmptyState() { return <div data-testid="empty-state" className="rounded-2xl border border-dashed border-slate-300 bg-white p-12 text-center"><CircleHelp className="mx-auto size-8 text-slate-400" /><p className="mt-3 font-heading font-extrabold text-slate-900">No scholarships matched your search.</p><p className="mt-1 text-sm text-slate-500">Try a different search or update your profile.</p></div>; }
function ErrorState({ message }: { message: string }) { return <div data-testid="error-state" className="rounded-2xl border border-rose-200 bg-rose-50 p-8 text-center"><CircleAlert className="mx-auto size-8 text-rose-600" /><p className="mt-3 font-bold text-rose-900">{message}</p></div>; }
function AuthRequired() { return <div data-testid="auth-required-state" className="rounded-2xl border border-amber-200 bg-amber-50 p-8 text-center"><LockMessage /><Link data-testid="auth-required-login-link" to="/login" className="mt-4 inline-flex items-center gap-2 font-bold text-teal-700">Sign in or load Demo Mode <ArrowRight className="size-4" /></Link></div>; }
function LockMessage() { return <><ShieldCheck className="mx-auto size-8 text-amber-700" /><p className="mt-3 font-bold text-amber-900">This workspace needs an active session.</p></>; }